    async touchSoulActivity(source='offline'){const a=soulAccount();if(!a.harvest)a.harvest={source,started_at:now(),expires_at:new Date(Date.now()+30*60000).toISOString(),earned:0};save();return ok(soulState())},
    async tickSoulHarvest(){const a=soulAccount();if(a.harvest&&Date.parse(a.harvest.expires_at)>Date.now()){a.balance+=100;a.harvest.earned=Number(a.harvest.earned||0)+100;a.transactions.unshift({id:id('soul'),tx_type:'HARVEST',amount:100,balance_after:a.balance,created_at:now()})}else a.harvest=null;save();return ok(soulState())},
    async purchaseSoulProduct(productKey){const a=soulAccount(),p=soulCatalog.find(x=>x.product_key===String(productKey));if(!p)return fail('PRODUCT_NOT_FOUND');if(a.balance<p.price)return fail('INSUFFICIENT_SOULDRAKMA');a.balance-=p.price;const type=p.product_type==='expansion'?'expansion':p.entitlement_key;let e=a.entitlements.find(x=>x.entitlement_type===type&&x.entitlement_key===p.entitlement_key);if(!e){e={entitlement_type:type,entitlement_key:p.entitlement_key,quantity:0};a.entitlements.push(e)}e.quantity+=1;a.transactions.unshift({id:id('soul'),tx_type:'PURCHASE',amount:-p.price,balance_after:a.balance,reason:p.product_key,created_at:now()});save();return ok(soulState())},
