    async reverseProgressionGrant(transactionId,reason=''){if(!canManage(state.progression.transactions.find(t=>String(t.id)===String(transactionId))?.table_id))return fail('GM_REQUIRED');const t=state.progression.transactions.find(x=>String(x.id)===String(transactionId)&&x.tx_type==='CHARACTER_GRANT');if(!t)return fail('GRANT_NOT_FOUND');if(state.progression.transactions.some(x=>x.tx_type==='CHARACTER_GRANT_REVERSAL'&&String(x.reference_id)===String(t.id)))return fail('ALREADY_REVERSED');const a=ensureProgressionAccount(t.table_id,t.character_id),w=ensureProgressionWallet(t.table_id);if(a.balance<Number(t.amount))return fail('POINTS_ALREADY_SPENT');a.balance-=Number(t.amount);w.balance+=Number(t.amount);w.lifetime_distributed=Math.max(0,Number(w.lifetime_distributed||0)-Number(t.amount));tx({table_id:t.table_id,character_id:t.character_id,amount:-Number(t.amount),balance_after:a.balance,tx_type:'CHARACTER_GRANT_REVERSAL',reason:String(reason||''),reference_id:String(t.id)});save();return ok({wallet:w,account:a})},
